# Let's try a local search (hill climbing or simulated annealing) to find a solution.
import random

def get_cost(x, y, n):
    cost = 0
    if sum(x) != 1:
        cost += abs(sum(x) - 1) * 10
    if sum(y) != 1:
        cost += abs(sum(y) - 1) * 10

    for k in range(1, n // 2 + 1):
        cx_k = sum(x[i] * x[(i + k) % n] for i in range(n))
        cy_k = sum(y[i] * y[(i + k) % n] for i in range(n))
        cost += abs(cx_k + cy_k + 2)
    return cost

def solve_local_search(n, iterations=100000):
    x = [1 if random.random() < 0.5 else -1 for _ in range(n)]
    y = [1 if random.random() < 0.5 else -1 for _ in range(n)]

    # Ensure sum is 1
    while sum(x) != 1:
        idx = random.randint(0, n - 1)
        x[idx] = -x[idx]
    while sum(y) != 1:
        idx = random.randint(0, n - 1)
        y[idx] = -y[idx]

    current_cost = get_cost(x, y, n)

    for _ in range(iterations):
        # Try flipping a bit in x or y, while maintaining the sum
        if random.random() < 0.5:
            # Flip two bits in x to keep sum constant
            i, j = random.sample(range(n), 2)
            if x[i] != x[j]:
                x[i], x[j] = -x[i], -x[j]
                new_cost = get_cost(x, y, n)
                if new_cost < current_cost or random.random() < 0.01:
                    current_cost = new_cost
                else:
                    x[i], x[j] = -x[i], -x[j]
        else:
            # Flip two bits in y to keep sum constant
            i, j = random.sample(range(n), 2)
            if y[i] != y[j]:
                y[i], y[j] = -y[i], -y[j]
                new_cost = get_cost(x, y, n)
                if new_cost < current_cost or random.random() < 0.01:
                    current_cost = new_cost
                else:
                    y[i], y[j] = -y[i], -y[j]

        if current_cost == 0:
            return x + y
    return None

print(solve_local_search(27, iterations=1000000))

import random

def get_correlations(x, y, n):
    corrs = []
    for k in range(1, n // 2 + 1):
        cx_k = sum(x[i] * x[(i + k) % n] for i in range(n))
        cy_k = sum(y[i] * y[(i + k) % n] for i in range(n))
        corrs.append(cx_k + cy_k)
    return corrs

def get_cost(corrs):
    return sum(abs(c + 2) for c in corrs)

def solve_hill_climbing(n, restarts=10, iterations=100000):
    for _ in range(restarts):
        x = [1] * ((n + 1) // 2) + [-1] * ((n - 1) // 2)
        y = [1] * ((n + 1) // 2) + [-1] * ((n - 1) // 2)
        random.shuffle(x)
        random.shuffle(y)

        current_corrs = get_correlations(x, y, n)
        current_cost = get_cost(current_corrs)

        for _ in range(iterations):
            # Try to flip two bits
            if random.random() < 0.5:
                i, j = random.sample(range(n), 2)
                if x[i] != x[j]:
                    x[i], x[j] = -x[i], -x[j]
                    new_corrs = get_correlations(x, y, n)
                    new_cost = get_cost(new_corrs)
                    if new_cost <= current_cost:
                        current_cost = new_cost
                        current_corrs = new_corrs
                    else:
                        x[i], x[j] = -x[i], -x[j]
            else:
                i, j = random.sample(range(n), 2)
                if y[i] != y[j]:
                    y[i], y[j] = -y[i], -y[j]
                    new_corrs = get_correlations(x, y, n)
                    new_cost = get_cost(new_corrs)
                    if new_cost <= current_cost:
                        current_cost = new_cost
                        current_corrs = new_corrs
                    else:
                        y[i], y[j] = -y[i], -y[j]

            if current_cost == 0:
                return x + y
    return None

print(solve_hill_climbing(27, restarts=10, iterations=500000))
